window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-43501\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειραψία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 238 na letra χ · nº geral 43501</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 entrelaçamento de braços (em luta) 2 luta corpo a corpo 3 combate 4 massagem leve; fricção. 〈χείρ, ἅπτω〉</p></section></article>\n<article id=\"entry-dgp-43502\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χείρεσι, χείρεσσι</h1><div class=\"entry-meta\"><span>DGP · ordem 239 na letra χ · nº geral 43502</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. pl. poét. de χείρ.</p></section></article>\n<article id=\"entry-dgp-43503\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειριδωτός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 240 na letra χ · nº geral 43503</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">guarnecido com mangas (veste oriental). 〈χειρίς〉</p></section></article>\n<article id=\"entry-dgp-43504\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 241 na letra χ · nº geral 43504</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. χειρίσω, át. χειριῶ, fut. pas. χειρισθήσομαι) 1 Medic. tratar; operar 2 manejar; governar com arte 3 dirigir; administrar. 〈χείρ〉</p></section></article>\n<article id=\"entry-dgp-43505\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χείριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 242 na letra χ · nº geral 43505</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que está nas mãos, em poder de alguém; submisso. 〈χείρ〉</p></section></article>\n<article id=\"entry-dgp-43506\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρίς, ῖδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 243 na letra χ · nº geral 43506</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 luva 2 manga longa (de veste persa) 3 meia. 〈χείρ〉</p></section></article>\n<article id=\"entry-dgp-43507\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χείριστος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 244 na letra χ · nº geral 43507</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">superl. de χείρων.</p></section></article>\n<article id=\"entry-dgp-43508\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροβλημάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 245 na letra χ · nº geral 43508</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tocar; apalpar.</p></section></article>\n<article id=\"entry-dgp-43509\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροβολέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 246 na letra χ · nº geral 43509</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lançar com a mão. 〈χείρ, βάλλω〉</p></section></article>\n<article id=\"entry-dgp-43510\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρόγραφον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 247 na letra χ · nº geral 43510</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 manuscrito 2 registro de dívida; caução. 〈χείρ, γράφω〉</p></section></article>\n<article id=\"entry-dgp-43511\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροδάϊκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 248 na letra χ · nº geral 43511</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dilacerado com as mãos. 〈χείρ, δαίζω〉</p></section></article>\n<article id=\"entry-dgp-43512\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρόδεικτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 249 na letra χ · nº geral 43512</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se pode apontar com a mão; visível. 〈χείρ, δείκνυμι〉</p></section></article>\n<article id=\"entry-dgp-43513\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροήθης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 250 na letra χ · nº geral 43513</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 doméstico; manso (animal) 2 amável; dócil; civilizado (pessoa) 3 condescendente; submisso 4 habituado a; familiarizado com, dat. 5 manejável; adaptável; familiar (coisa). 〈χείρ, ἧθος〉</p></section></article>\n<article id=\"entry-dgp-43514\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρόκμητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 251 na letra χ · nº geral 43514</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 feito à mão; trabalhado com arte 2 artificial. 〈χείρ, κάμνω〉</p></section></article>\n<article id=\"entry-dgp-43515\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρκοπέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 252 na letra χ · nº geral 43515</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cortar as mãos de alguém, ac. ♦ pas. 2 ter as mãos cortadas. 〈χείρ, κόπτω〉</p></section></article>\n<article id=\"entry-dgp-43516\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροκρασία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 253 na letra χ · nº geral 43516</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">χειροκρατία.</p></section></article>\n<article id=\"entry-dgp-43517\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροκρατία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 254 na letra χ · nº geral 43517</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dominação pela força; poder despótico. 〈χείρ, κρατέω〉</p></section></article>\n<article id=\"entry-dgp-43518\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρόμακτρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 255 na letra χ · nº geral 43518</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 toalha de mão 2 véu. 〈χείρ, μάσσω〉</p></section></article>\n<article id=\"entry-dgp-43519\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρομάχα, ας</h1><div class=\"entry-meta\"><span>DGP · ordem 256 na letra χ · nº geral 43519</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) dór. que dá soco; que combate com as mãos, nome de uma facção de Mileto. 〈χειρομάχος〉</p></section></article>\n<article id=\"entry-dgp-43520\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρομάχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 257 na letra χ · nº geral 43520</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que combate ou luta com as mãos. 〈χείρ, μάχομαι〉</p></section></article>\n<article id=\"entry-dgp-43521\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρομύλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 258 na letra χ · nº geral 43521</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">moinho manual.</p></section></article>\n<article id=\"entry-dgp-43522\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρονομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 259 na letra χ · nº geral 43522</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐχειρονόμησα) 1 na dança, mover em cadência as mãos, os braços ou as pernas 2 (pugilista) mover os braços para aparar golpes. 〈χείρ, νέμω〉</p></section></article>\n<article id=\"entry-dgp-43523\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρονομία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 260 na letra χ · nº geral 43523</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 movimento cadenciado dos braços; gesticulação cadenciada 2 no pugilato, quironomia. 〈χειρονομέω〉</p></section></article>\n<article id=\"entry-dgp-43524\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροπέδη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 261 na letra χ · nº geral 43524</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">algemas. 〈χείρ, πέδη〉</p></section></article>\n<article id=\"entry-dgp-43525\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροπληθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 262 na letra χ · nº geral 43525</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">grande o bastante para encher a mão. 〈χείρ, πλῆθος〉</p></section></article>\n<article id=\"entry-dgp-43526\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροποιέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 263 na letra χ · nº geral 43526</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">executar com as próprias mãos. 〈χείρ, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-43527\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροποίητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 264 na letra χ · nº geral 43527</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 feito por mão humana; artificial 2 fictício. 〈χειροποιέομαι〉</p></section></article>\n<article id=\"entry-dgp-43528\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρόσοφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 265 na letra χ · nº geral 43528</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">hábil em mover as mãos, em gesticular com cadência. 〈χείρ, σοφός〉</p></section></article>\n<article id=\"entry-dgp-43529\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρότερος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 266 na letra χ · nº geral 43529</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">χείρων.</p></section></article>\n<article id=\"entry-dgp-43530\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροτέχνημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 267 na letra χ · nº geral 43530</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">obra de arte; trabalho feito à mão. 〈χείρ, τέχνη〉</p></section></article>\n<article id=\"entry-dgp-43531\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροτέχνης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 268 na letra χ · nº geral 43531</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 artesão; artista 2 artífice de, gen.: χ. πολέμου plut. artífice da guerra, χ. ἰατορίας sóf. perito em medicina. 〈χείρ, τέχνη〉</p></section></article>\n<article id=\"entry-dgp-43532\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροτεχνία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 269 na letra χ · nº geral 43532</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">arte manual. 〈χειροτέχνης〉</p></section></article>\n<article id=\"entry-dgp-43533\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροτεχνικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 270 na letra χ · nº geral 43533</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que concerne às artes manuais; manufatureiro 2 hábil nas artes dos artesãos ♦ ἡ χειροτεχνική 3 arte manual. 〈χειροτέχνης〉</p></section></article>\n<article id=\"entry-dgp-43534\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροτονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 271 na letra χ · nº geral 43534</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. χειροτονήσω, aor. ἐχειροτόνησα, perf. κεχειροτόνηκα; pas. aor. ἐχειροτονήθην, perf. κεχειροτόνημαι) 1 erguer a mão para votar; votar com a mão erguida 2 eleger por voto alguém, ac., para uma função, ac., εἰς e ac. ou ἐπί e gen.: Τιμόθεον στρατηγὸν ἐχειροτόνησαν xen. elegeram Timóteo estratego, εἰς τὴν ἀγορὰν χειροτονεῖν τοὺς ταξιάρχους... οὐκ ἐπὶ πόλεμον dem. eleger os taxiarcas para a função pública e não para a guerra 3 intr. decidir por voto; votar algo, ac. ou inf.: ὁ δῆμος ἐχειροτόνησεν πρέσβεις πέμπειν ὑπὲρ εἰρήνης ésqn. o povo votou o envio de embaixadores pela paz ♦ pas. 4 ser eleito por voto para uma função: χειροτονηθεὶς ἢ λαχών plat. designado pelo voto ou por sorteio, ἐπὶ τοῦτ᾽ ἐχειροτονήθησαν lís. para isto foram eleitos. 〈χειροτόνος〉</p></section></article>\n<article id=\"entry-dgp-43535\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροτονητός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 272 na letra χ · nº geral 43535</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 designado por votação com a mão erguida; eleito 2 eletivo (cargo). 〈χειροτονέω〉</p></section></article>\n<article id=\"entry-dgp-43536\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροτονία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 273 na letra χ · nº geral 43536</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 voto com as mãos erguidas; votação 2 sufrágio; voto; voz 3 ação de estender a mão. 〈χειροτόνος〉</p></section></article>\n<article id=\"entry-dgp-43537\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειροτόνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 274 na letra χ · nº geral 43537</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se faz estendendo as mãos (súplica). 〈χείρ, τείνω〉</p></section></article>\n<article id=\"entry-dgp-43538\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρουργέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 275 na letra χ · nº geral 43538</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐχειρούργησα; pas. χειρουργοῦμαι, aor. ἐχειρουργήθην, m.-q.-perf. ἐκεχειρούργητο) 1 realizar com as mãos; executar manualmente 2 fazer um trabalho manual 3 exercer uma profissão 4 Medic. fazer uma operação; operar (pessoa) 5 construir 6 tocar um instrumento 7 usar de violência. 〈χειρουργός〉</p></section></article>\n<article id=\"entry-dgp-43539\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρουργία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 276 na letra χ · nº geral 43539</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 trabalho manual 2 exercício de uma profissão ou de uma arte 3 Medic. operação cirúrgica; cirurgia 4 execução; realização. 〈χειρουργός〉</p></section></article>\n<article id=\"entry-dgp-43540\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρουργικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 277 na letra χ · nº geral 43540</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 feito com as mãos; manual 2 de uma arte ou de uma profissão 3 técnico ♦ ἡ χειρουργική 4 arte do cirurgião; cirurgia. 〈χειρουργός〉</p></section></article>\n<article id=\"entry-dgp-43541\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρουργός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 278 na letra χ · nº geral 43541</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que trabalha com as mãos; que executa com as mãos 2 que se dedica a uma arte ou profissão, περί e ac. 3 manual (arte) ♦ ὁ χειρουργός 4 cirurgião 5 pl. artesãos; artistas. 〈χείρ, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-43542\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χείρους</h1><div class=\"entry-meta\"><span>DGP · ordem 279 na letra χ · nº geral 43542</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pl. de χείρων.</p></section></article>\n<article id=\"entry-dgp-43543\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 280 na letra χ · nº geral 43543</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 subjugar; domar: χειροῦν τὸν ἐλέφαντα el. domar o elefante, πρὸς βίαν χειροῦν ar. submeter pela força ♦ méd. 2 submeter; subjugar; dominar: τοὺς ἐναντίους χειροῦσθαι her. subjugar os inimigos, Λακεδαιμόνιους σφίσι χειρώσεσθαι tuc. submeter os lacedemônios a sua autoridade 3 persuadir; seduzir; convencer: χειροῦσθαί τινα λόγοις plat. convencer alguém com argumentos, ἡ ὄρχησις κεχείρωται τοὺς ἀνθρώπους luc. a dança seduz os homens 4 refutar; desmontar; destruir (opinião, argumento) 5 agarrar; capturar; recuperar: δάμαρτα τὴν ἐμὴν χειρώσομαι eur. vou recuperar minha esposa. 〈χείρ〉</p></section></article>\n<article id=\"entry-dgp-43544\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χείρωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 281 na letra χ · nº geral 43544</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação manual; execução manual: χειρώματα τυμβοχόα ésql. libações tumulares vertidas manualmente, χ. θανάσιμον sóf. ação mortal executada com as mãos, homicídio 2 homicídio. 〈χειρόω〉</p></section></article>\n<article id=\"entry-dgp-43545\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χείρων, ων, ον,</h1><div class=\"entry-meta\"><span>DGP · ordem 282 na letra χ · nº geral 43545</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος, pl. nom. e ac. contr. χείρους (comp. de κακός) 1 inferior; pior (pessoa): σὺ μὲν ἐσθλός, ἐγὼ δὲ πολὺ χείρων hom. tu tens valor mas eu sou inferior, χείρων τὴν διάνοιαν isócr. inferior em inteligência, χείρων εἰς τὴν ἀρετήν plat. inferior em virtude 2 de qualidade inferior (coisa): χεῖρον ἄεθλον hom. prêmio de baixo valor, ὑποδήματα τὰ μὲν χείρω, τὰ δὲ βελτίω xen. uns calçados mais ordinários, outros melhores 3 pior: χείρων νόσος eur. doença pior, mais grave, χείρων τιμωρία n.t. castigo pior, mais severo 4 χεῖρον (ἐστι não expresso) é ruim; é melhor não: οὐ γὰρ χεῖρον πολλάκις ἀκούειν plat. não é ruim ouvir muitas vezes ♦ χεῖρον adv. 5 de maneira inferior; mal: χεῖρον βουλεύσασθαι tuc. deliberar mal, χεῖρον ζῆν plat. viver mal ♦ οἱ χείρονες 6 os inferiores ♦ τὸ χεῖρον 7 inferioridade; o pior: ἐπὶ τὸ χεῖρον μεταβάλλει ἑαυτόν plat. ele se modifica para o pior, τὰ χείρω προαιρεῖσθαι isócr. escolher o pior partido. 〈χέρης〉</p></section></article>\n<article id=\"entry-dgp-43546\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Χείρων, ωνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 283 na letra χ · nº geral 43546</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Quirão, centauro.</p></section></article>\n<article id=\"entry-dgp-43547\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρῶναξ, ακτος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 284 na letra χ · nº geral 43547</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 operário; artesão 2 artífice; autor de, gen. 〈χείρ, ἄναξ〉</p></section></article>\n<article id=\"entry-dgp-43548\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χειρωναξία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 285 na letra χ · nº geral 43548</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">arte manual; profissão. 〈χειρῶναξ〉</p></section></article>\n<article id=\"entry-dgp-43549\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χεῖσθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 286 na letra χ · nº geral 43549</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. méd. pas. de χέω.</p></section></article>\n<article id=\"entry-dgp-43550\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χείσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 287 na letra χ · nº geral 43550</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de χανδάνω.</p></section></article>\n<article id=\"entry-dgp-43551\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χελιδοῖ</h1><div class=\"entry-meta\"><span>DGP · ordem 288 na letra χ · nº geral 43551</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">voc. de χελιδών.</p></section></article>\n<article id=\"entry-dgp-43552\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Χελιδόνεαι</h1><div class=\"entry-meta\"><span>DGP · ordem 289 na letra χ · nº geral 43552</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Χελιδόνιαι νῆσοι (αἱ) Ilhas das Andori­nhas, na costa da Lícia. 〈χελιδών〉</p></section></article>\n<article id=\"entry-dgp-43553\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χελιδών, όνος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 290 na letra χ · nº geral 43553</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 andorinha 2 andorinha do mar, peixe voador 3 cavidade sob o casco dos cavalos 4 pl., com., genitais da mulher.</p></section></article>\n<article id=\"entry-dgp-43554\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χέλυμνα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 291 na letra χ · nº geral 43554</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">χελώνη.</p></section></article>\n<article id=\"entry-dgp-43555\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χελύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 292 na letra χ · nº geral 43555</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lábio 2 maxilar.</p></section></article>\n<article id=\"entry-dgp-43556\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χέλυς, υος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 293 na letra χ · nº geral 43556</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tartaruga 2 lira feita com o casco da tartaruga 3 Astron. Lira, constelação 4 Anat. tórax. 〈χελώνη〉</p></section></article>\n<article id=\"entry-dgp-43557\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χελώνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 294 na letra χ · nº geral 43557</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tartaruga 2 casco de tartaruga 3 Mil. escudo que abriga sapadores e máquinas num assédio 4 Mil. cobertura feita de escudos ao sitiar uma fortificação 5 escabelo; tamborete 6 caixa acústica da lira feita com o casco da tartaruga 7 montículo de areia.</p></section></article>\n<article id=\"entry-dgp-43558\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χελώνιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 295 na letra χ · nº geral 43558</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 casco de tartaruga ou de caranguejo 2 quelônio, moeda de Tênedos com uma figura de tartaruga 3 parte arqueada do dorso; lombo. 〈χελώνη〉</p></section></article>\n<article id=\"entry-dgp-43559\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χενόσιρις (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 296 na letra χ · nº geral 43559</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">hera. [egípcio]</p></section></article>\n<article id=\"entry-dgp-43560\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χέρας</h1><div class=\"entry-meta\"><span>DGP · ordem 297 na letra χ · nº geral 43560</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. poét. e jôn. de χείρ.</p></section></article>\n<article id=\"entry-dgp-43561\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χέραδος</h1><div class=\"entry-meta\"><span>DGP · ordem 298 na letra χ · nº geral 43561</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só ac. sing. (τό) monte de pedriscos e de areia trazidos pela água; cascalho.</p></section></article>\n<article id=\"entry-dgp-43562\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερειότερος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 299 na letra χ · nº geral 43562</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">χείρων.</p></section></article>\n<article id=\"entry-dgp-43563\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερείων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 300 na letra χ · nº geral 43563</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος ép. = χείρων.</p></section></article>\n<article id=\"entry-dgp-43564\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χέρης</h1><div class=\"entry-meta\"><span>DGP · ordem 301 na letra χ · nº geral 43564</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só dat. χέρηϊ, ac. χέρηα, nom. pl. χέρηες, ac. pl. n. χέρηα (masc., fem.) 1 de baixa condição; desprezível 2 comp. mais fraco; mais frouxo; inferior a, gen. 〈χείρων〉</p></section></article>\n<article id=\"entry-dgp-43565\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερμάδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 302 na letra χ · nº geral 43565</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pedra usada em combates como projétil.</p></section></article>\n<article id=\"entry-dgp-43566\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερμάδιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 303 na letra χ · nº geral 43566</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">do tamanho de uma pedra que se lança contra o inimigo. 〈χερμάς〉</p></section></article>\n<article id=\"entry-dgp-43567\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερμάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 304 na letra χ · nº geral 43567</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pedregulho 2 pedra de funda 3 quarto de rocha 4 cascalho 5 pedra tumular.</p></section></article>\n<article id=\"entry-dgp-43568\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερνής, ῆτος</h1><div class=\"entry-meta\"><span>DGP · ordem 305 na letra χ · nº geral 43568</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) = χερνήτης.</p></section></article>\n<article id=\"entry-dgp-43569\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερνήτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 306 na letra χ · nº geral 43569</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 operário; proletário 2 pobre; miserável. 〈χείρ〉</p></section></article>\n<article id=\"entry-dgp-43570\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερνῆτις, ιδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 307 na letra χ · nº geral 43570</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de χερνήτὴ.</p></section></article>\n<article id=\"entry-dgp-43571\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χέρνιβα</h1><div class=\"entry-meta\"><span>DGP · ordem 308 na letra χ · nº geral 43571</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. sing. de χέρνιψ e pl. de χέρνιβον.</p></section></article>\n<article id=\"entry-dgp-43572\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερνίβεσσι</h1><div class=\"entry-meta\"><span>DGP · ordem 309 na letra χ · nº geral 43572</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. pl. poét. de χέρνιψ.</p></section></article>\n<article id=\"entry-dgp-43573\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χέρνιβον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 310 na letra χ · nº geral 43573</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pequena bacia para lavar as mãos 2 urinol; penico. 〈χέρνιψ〉</p></section></article>\n<article id=\"entry-dgp-43574\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερνίπτω,</h1><div class=\"entry-meta\"><span>DGP · ordem 311 na letra χ · nº geral 43574</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ger. méd. χερνίπτομαι (fut. χερνίψομαι, aor. ἐχερνιψάμην, aor. pas. χερνιφθείς) 1 lavar-se as mãos com água lustral 2 verter, derramar água lustral. 〈χέρνιψ〉</p></section></article>\n<article id=\"entry-dgp-43575\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χέρνιψ, ιβος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 312 na letra χ · nº geral 43575</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 água para lavar as mãos antes da refeição ou antes de cerimônia religiosa: χέρνιβας νέμειν sóf. permitir a participação nas abluções, i.e., nos sacrifícios, χερνίβων κοινωνός ésql. que participa das abluções, i.e., comensal 2 pl. purificações com água lustral. 〈χείρ, νίπτω〉</p></section></article>\n<article id=\"entry-dgp-43576\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χεροῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 313 na letra χ · nº geral 43576</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. e dat. dual de χείρ.</p></section></article>\n<article id=\"entry-dgp-43577\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερόπληκτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 314 na letra χ · nº geral 43577</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">atingido pela mão. 〈χείρ, πλήσσω〉</p></section></article>\n<article id=\"entry-dgp-43578\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Χερρονήσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 315 na letra χ · nº geral 43578</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da Quersoneso da Trácia. 〈Χερρό­νησος〉</p></section></article>\n<article id=\"entry-dgp-43579\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Χερρόνησος</h1><div class=\"entry-meta\"><span>DGP · ordem 316 na letra χ · nº geral 43579</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = Χερσόνησος.</p></section></article>\n<article id=\"entry-dgp-43580\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χέρρος</h1><div class=\"entry-meta\"><span>DGP · ordem 317 na letra χ · nº geral 43580</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">χέρσος.</p></section></article>\n<article id=\"entry-dgp-43581\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερσαῖος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 318 na letra χ · nº geral 43581</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 da terra firme; terrestre 2 estabelecido sobre terra firme (cidade) 3 que se desloca por terra (infantaria, aparato bélico) ♦ ἡ χερσαῖος 4 terra firme. 〈χέρσος〉</p></section></article>\n<article id=\"entry-dgp-43582\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερσεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 319 na letra χ · nº geral 43582</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 viver, habitar em terra firme 2 buscar a terra firme 3 ser terra firme 4 (terra) permanecer sem cultivo, improdutiva ♦ pas. 5 tornar-se terra firme 6 tornar-se sem cultivo, baldio. 〈χέρσος〉</p></section></article>\n<article id=\"entry-dgp-43583\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερσί</h1><div class=\"entry-meta\"><span>DGP · ordem 320 na letra χ · nº geral 43583</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. pl. de χείρ.</p></section></article>\n<article id=\"entry-dgp-43584\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χέρσονδε</h1><div class=\"entry-meta\"><span>DGP · ordem 321 na letra χ · nº geral 43584</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. para terra firme; em direção ao continente. 〈χέρσος, -δε〉</p></section></article>\n<article id=\"entry-dgp-43585\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Χερσονήσιος</h1><div class=\"entry-meta\"><span>DGP · ordem 322 na letra χ · nº geral 43585</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e Χερρονήσιος, α, ον da Quersoneso da Trácia. 〈Χερσόνησος〉</p></section></article>\n<article id=\"entry-dgp-43586\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερσονησοειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 323 na letra χ · nº geral 43586</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">semelhante a uma península. 〈Χερσόνησος, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-43587\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερσόνησος</h1><div class=\"entry-meta\"><span>DGP · ordem 324 na letra χ · nº geral 43587</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, át., χερρόνησος, ου (ἡ) 1 península; cabo ♦ Χερσόνησος 2 Quersoneso, n. de diversas penínsulas.</p></section></article>\n<article id=\"entry-dgp-43588\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χέρσος</h1><div class=\"entry-meta\"><span>DGP · ordem 325 na letra χ · nº geral 43588</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e χέρρος, ος, ον 1 seco; sólido; duro 2 da terra firme; continental 3 árido; sem cultivo; baldio (terra) 4 privado de filhos; estéril (mulher).</p></section></article>\n<article id=\"entry-dgp-43589\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χερσόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 326 na letra χ · nº geral 43589</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tornar sem cultivo; tornar estéril.</p></section></article>\n<article id=\"entry-dgp-43590\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χεσείω</h1><div class=\"entry-meta\"><span>DGP · ordem 327 na letra χ · nº geral 43590</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ter vontade de defecar.</p></section></article>\n<article id=\"entry-dgp-43591\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χεῦα</h1><div class=\"entry-meta\"><span>DGP · ordem 328 na letra χ · nº geral 43591</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aor. ép. de χέω.</p></section></article>\n<article id=\"entry-dgp-43592\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χεῦμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 329 na letra χ · nº geral 43592</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fluxo; corrente de um rio 2 escoamento 3 avalanche 4 libação 5 pl. vaso para as libações 6 filamento de metal fundido na borda da couraça. 〈χέω〉</p></section></article>\n<article id=\"entry-dgp-43593\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χεύομεν</h1><div class=\"entry-meta\"><span>DGP · ordem 330 na letra χ · nº geral 43593</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1ª pl. aor. subj. ép. de χέω.</p></section></article>\n<article id=\"entry-dgp-43594\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χεύω1, εις, ει</h1><div class=\"entry-meta\"><span>DGP · ordem 331 na letra χ · nº geral 43594</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. ép. de χέω.</p></section></article>\n<article id=\"entry-dgp-43595\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χεύω2, ῂ, ῃ</h1><div class=\"entry-meta\"><span>DGP · ordem 332 na letra χ · nº geral 43595</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. aor. ép. de χέω.</p></section></article>\n<article id=\"entry-dgp-43596\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χέω</h1><div class=\"entry-meta\"><span>DGP · ordem 333 na letra χ · nº geral 43596</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. χέω, ép. χεύω, aor. ἔχεα, ép. ἔχευα, perf. desus.; méd. impf. ἐχεόμην, fut. χέομαι, aor. ἐχεάμην, aor.2 ἐχύμην, perf. κέχυμαι, m.-q.-perf. ἐκεχύμην; pas. fut. χυθήσομαι, aor. ἐχύθην, perf. κέχυμαι, m.-q.-perf. ἐκεχύμην) ativa 1 fazer escorrer; espalhar; verter; derramar (líquido) 2 derramar; espalhar; verter 3 fazer cair; despejar; depositar média 4 despejar; derramar; espalhar (líquido) 5 espalhar; derramar; deixar cair, fazer cair, lançar 6 despejar; emitir; proferir méd. pas. 7 (líquido) verter-se; derramar-se; espalhar-se 8 ser derramado; ser espalhado; ser amontoado; jogar-se 9 (homens e animais) avançar em grupo, em bando 10 (ar, vapor) espalhar-se; verter-se 11 afrouxar-se; amolecer 12 perf. estar impregnado; estar ligado a; ser empenhado; ser engajado 1 ἣ τε κατ᾽ αἰγίλιπος πέτρης δνοφερὸν χέει ὕδωρ hom. [fonte] que, de uma rocha escarpada, faz verter uma água negra, τοῖσι δὲ κήρυκες μὲν ὕδωρ ἐπὶ χεῖρας ἔχευον hom. os arautos derramavam água sobre as mãos deles, δάκρυα θερμὰ χέοντες hom. vertendo lágrimas quentes, χέουσα τάσδε κηδείους χοάς ésql. derramando libações fúnebres 2 πολλὴν ἠέρα χεῦε hom. espalhou uma brisa abundante, κὰκ κεφαλῆς χεῦεν πολὺ κάλλος hom. espalhou sobre sua cabeça uma grande beleza, πνεῦμα χέων ἐν αὐλοῖς a.p. vertendo um sopro na flauta, χέει πολυηχέα φωνήν hom. verte, i.e., faz ouvir longos trinados, ἐπὶ θρῆνόν τε πολύφαμον ἔχεαν pínd. fizeram ouvir sobre ele [o túmulo] um treno glorioso, Ἑλλάδος φθόγγον χέουσα ésql. fazendo ouvir uma voz grega 3 ἐν δέ μοι ἄλφιτα χεῦον ἐϋρραφέεσσι δοροίσι hom. verte para mim farinha em sacos bem costurados, φύλλα ἄνεμος χαμάδις χέει hom. o vento faz cair as folhas no chão, κατὰ δ᾽ ἥνια χεῦεν ἔραζε hom. deixou cair as rédeas no chão, χέειν σῆμα hom. amontoar terra para fazer um túmulo 4 χοὴν ou χοὰς χεῖσθαι hom. derramar libações, κρατῆρα χεῖσθαι plut. despejar o conteúdo de uma cratera 5 ἀμφὶ δ᾽ ἑὸν φίλον υἱὸν ἐχεύατο πήχεε λευκώ hom. lançou os alvos braços em volta do seu amado filho, κόνιν αἰθαλόεσσαν χεύατο κὰκ κεφαλῆς hom. espalhou cinza negra sobre sua cabeça, βέλεα στονόεντα χέοντο hom. lançavam as flechas que fazem gemer 6 κωμῳδικὰ πολλὰ χέασθαι ar. despejar muitas falas cômicas 7 ἀπ᾽ ὀφθαλμῶν χύτο δάκρυα hom. lágrimas escorriam dos olhos, ἐφ᾽ ἁλὸς πολιῆς χέχυται λιμέσιν τε καὶ ἀκταῖς hom. [a neve] está espalhada sobre os portos e as falésias junto ao mar cinzento, φονίας σταγόνας χυμένας ἐς πέδον ésql. gotas de sangue derramadas sobre a terra, ποτοῦ χυθέντος ἐς γῆν sóf. tendo o líquido sido despejado no chão 8 ἀμφὶ δὲ δεσμοὶ ἔχυντο hom. em torno deles estenderam-se os laços, ἐν τᾷδ᾽ ἄφθιτον νάσῳ κέχυται Λιβύας σπέρμα pínd. a semente imortal da Líbia está espalhada nesta ilha, πλόκαμος γένυν παρ᾽ αὐτὴν κεχυμένος eur. cachos espalhados nas faces, ἐπ᾽ ἀλλήλοισι κέχυντο hom. [cadáveres] estavam amontoados uns sobre os outros, ἐπὶ ψαμάθοισι κέχυνται hom. [peixes] amontoados sobre a areia, ἀμφ᾽ αὐτῷ χυμένη hom. lançando-se envolvendo-o, i.e., abraçando-o 9 ἐκ νηῶν ἐκέχυντο hom. [os mirmidões] em bandos chegavam dos navios, ἑμὲ δακρυόεντες ἔχυντο hom. afluíram em prantos ao meu encontro 10 ἀὴρ χεῖται plat. a bruma se espalha, circula, χῦτο πάλιν ἀήρ hom. o vapor se dissipou, κέχυτ᾽ ἀχλὺς κατὰ ὀφθαλμῶν hom. uma névoa espalhou-se sobre seus olhos, ἀμφὶ δέ οἱ θάνατος χύτο hom. a morte estendeu-se sobre ele, οὔ κέ μοι ὕπνος ἐπὶ βλεφάροισι χυθείη hom. o sono não se espalharia sobre minhas pálpebras, κέχυται νόσος sóf. uma doença abateu-se [sobre Héracles] 11 τὰ κεχυμένα plat. as coisas frouxas, moles, sem consistência sólida, κεχυμέναι σάρκες artt. carnes moles, κεχυμένη φράσις d.h. estilo relaxado 12 ἐχύθη οἱ θυμός a.r. a alegria encheu-lhe o coração, ∆ᾶλος ἐν ᾇ κέχυμαι pínd. Delos, na qual me sinto absorvido, κεχυμένος εἰς τὰ ἀφροδίσια luc. entregue aos prazeres do amor, πρὸς πᾶσαν ἡδονήν κεχυμένος alcífr. entregue a todos os prazeres.</p></section></article>\n<article id=\"entry-dgp-43597\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χέω, χεῖ, χεῖ</h1><div class=\"entry-meta\"><span>DGP · ordem 334 na letra χ · nº geral 43597</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de χέω.</p></section></article>\n<article id=\"entry-dgp-43598\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χέω, ῂ, ῃ</h1><div class=\"entry-meta\"><span>DGP · ordem 335 na letra χ · nº geral 43598</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. pres. ou aor. de χέω.</p></section></article>\n<article id=\"entry-dgp-43599\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χἠ</h1><div class=\"entry-meta\"><span>DGP · ordem 336 na letra χ · nº geral 43599</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase poét. de καὶ ἡ.</p></section></article>\n<article id=\"entry-dgp-43600\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">χηλευτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 337 na letra χ · nº geral 43600</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tecido em malha.</p></section></article>\n";
